module tb_TopModule;
    reg a, b, c, d;
    wire out;

    TopModule uut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .out(out)
    );

    // Reference model matching the K-map specification
    function reg_model(input ra, rb, rc, rd);
        // cd rows: 00, 01, 11, 10
        // ab cols: 00, 01, 11, 10
        reg [1:0] cd_code, ab_code;
        begin
            cd_code = {rc, rd};
            ab_code = {ra, rb};
            case (cd_code)
                2'b00: begin
                    case (ab_code)
                        2'b00: reg_model = 0;
                        2'b01: reg_model = 1;
                        2'b11: reg_model = 0;
                        2'b10: reg_model = 1;
                    endcase
                end
                2'b01: begin
                    case (ab_code)
                        2'b00: reg_model = 1;
                        2'b01: reg_model = 0;
                        2'b11: reg_model = 1;
                        2'b10: reg_model = 0;
                    endcase
                end
                2'b11: begin
                    case (ab_code)
                        2'b00: reg_model = 0;
                        2'b01: reg_model = 1;
                        2'b11: reg_model = 0;
                        2'b10: reg_model = 1;
                    endcase
                end
                2'b10: begin
                    case (ab_code)
                        2'b00: reg_model = 1;
                        2'b01: reg_model = 0;
                        2'b11: reg_model = 1;
                        2'b10: reg_model = 0;
                    endcase
                end
            endcase
        end
    endfunction

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            {a, b, c, d} = i[3:0];
            #1;
            if (out !== reg_model(a, b, c, d)) begin
                $display("SELFTEST FAIL: a=%b b=%b c=%b d=%b -> got %b, expected %b",
                         a, b, c, d, out, reg_model(a, b, c, d));
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
